// 获取两个月的账单数据
// 使用 $input.all() 获取所有输入
const allInputs = $input.all();

if (allInputs.length === 0) {
  return [{ json: { error: '没有收到数据' } }];
}

// 将输入按来源分组
// n8n 多输入时，数据会按输入节点的顺序合并
// 需要根据实际的输入索引来分组
const currentMonth = [];
const lastMonth = [];

// 方法：直接按 pairedItem.input 分组
for (const item of allInputs) {
  if (item.pairedItem && typeof item.pairedItem.input === 'number') {
    if (item.pairedItem.input === 0) {
      currentMonth.push(item);
    } else if (item.pairedItem.input === 1) {
      lastMonth.push(item);
    }
  }
}

// 如果上面的方法失败，尝试按顺序分组（假设前后各一半）
if (currentMonth.length === 0 && lastMonth.length === 0) {
  const midPoint = Math.floor(allInputs.length / 2);
  for (let i = 0; i < allInputs.length; i++) {
    if (i < midPoint) {
      currentMonth.push(allInputs[i]);
    } else {
      lastMonth.push(allInputs[i]);
    }
  }
}

if (currentMonth.length === 0 || lastMonth.length === 0) {
  return [{ json: { 
    error: '数据分组失败',
    totalInputs: allInputs.length,
    currentMonthCount: currentMonth.length,
    lastMonthCount: lastMonth.length
  }}];
}

// 构建上月账单映射表（以 Resource 为唯一标识）
const lastMonthMap = new Map();
for (const item of lastMonth) {
  const row = item.json;
  const resourceName = row.Resource || '';
  if (resourceName) {
    lastMonthMap.set(resourceName.trim(), {
      cost: parseFloat(row.CostUSD || row.Cost || 0),
      resourceGroup: row.ResourceGroup || '',
      subscription: row.SubscriptionName || '',
      resourceType: row.ResourceType || '',
      location: row.ResourceLocation || '',
      currency: row.Currency || 'USD'
    });
  }
}

// 对比分析
const results = [];
const processedResources = new Set();

// 处理本月账单（以本月为基准）
for (const item of currentMonth) {
  const row = item.json;
  const resourceName = (row.Resource || '').trim();

  if (!resourceName) continue;

  const currentCost = parseFloat(row.CostUSD || 0);
  const lastMonthData = lastMonthMap.get(resourceName);
  const lastCost = lastMonthData ? lastMonthData.cost : 0;
  const diff = currentCost - lastCost;

  // 判断 Remark
  let remark = '';
  if (!lastMonthData) {
    remark = 'New - 新增资源';
  } else if (diff !== 0) {
    remark = `Cost change: ${diff > 0 ? '+' : ''}${diff.toFixed(2)} USD (${((diff / lastCost) * 100).toFixed(2)}%)`;
  } else {
    remark = 'No change';
  }

  // 保留本月的所有字段（除了 Tags, Cost, Currency）
  results.push({
    ResourceGroup: row.ResourceGroup || '',
    ResourceGroupId: row.ResourceGroupId || '',
    SubscriptionName: row.SubscriptionName || '',
    SubscriptionId: row.SubscriptionId || '',
    Resource: resourceName,
    ResourceId: row.ResourceId || '',
    ResourceType: row.ResourceType || '',
    ResourceLocation: row.ResourceLocation || '',
    'CostUSD (Current Month)': currentCost.toFixed(2),
    'CostUSD (Last Month)': lastCost.toFixed(2),
    'Difference': diff.toFixed(2),
    Remark: remark
  });

  processedResources.add(resourceName);
}

// 添加上月有但本月没有的资源（已删除）
for (const [resourceName, data] of lastMonthMap.entries()) {
  if (!processedResources.has(resourceName)) {
    results.push({
      ResourceGroup: data.resourceGroup,
      ResourceGroupId: '',
      SubscriptionName: data.subscription,
      SubscriptionId: '',
      Resource: resourceName,
      ResourceId: '',
      ResourceType: data.resourceType,
      ResourceLocation: data.location,
      'CostUSD (Current Month)': '0.00',
      'CostUSD (Last Month)': data.cost.toFixed(2),
      'Difference': (-data.cost).toFixed(2),
      Remark: 'Deleted - 资源已删除'
    });
  }
}

// 按 Remark 排序：新增 → 已删除 → 变化大的
results.sort((a, b) => {
  const getOrder = (remark) => {
    if (remark.startsWith('New')) return 1;
    if (remark.startsWith('Deleted')) return 2;
    if (remark.startsWith('Cost change')) return 3;
    return 4;
  };
  const orderDiff = getOrder(a.Remark) - getOrder(b.Remark);
  if (orderDiff !== 0) return orderDiff;
  return Math.abs(parseFloat(b.Difference)) - Math.abs(parseFloat(a.Difference));
});

return results.map(r => ({ json: r }));
